package io.github.foodjournal.infrastructure.openai;

import com.fasterxml.jackson.databind.*;
import io.github.foodjournal.application.*;
import io.github.foodjournal.config.BotProperties;
import java.util.*;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component public class OpenAiIntentInterpreter implements IntentInterpreter {
 private final RestClient client; private final BotProperties props; private final ObjectMapper mapper;
 public OpenAiIntentInterpreter(RestClient.Builder builder,BotProperties props,ObjectMapper mapper){client=builder.baseUrl("https://api.openai.com/v1").build();this.props=props;this.mapper=mapper;}
 @Override public JournalIntent interpret(String message){if(props.openaiApiKey()==null||props.openaiApiKey().isBlank())return safe();try{Map<String,Object> nullableNumber=Map.of("type",List.of("number","null"));Map<String,Object> nullableInteger=Map.of("type",List.of("integer","null"));Map<String,Object> item=Map.of("type","object","additionalProperties",false,"properties",Map.ofEntries(Map.entry("name",Map.of("type",List.of("string","null"))),Map.entry("grams",nullableNumber),Map.entry("totalCalories",nullableInteger),Map.entry("caloriesPer100g",nullableInteger),Map.entry("proteinGrams",nullableNumber),Map.entry("carbsGrams",nullableNumber),Map.entry("fatGrams",nullableNumber),Map.entry("barcode",Map.of("type",List.of("string","null")))),"required",List.of("name","grams","totalCalories","caloriesPer100g","proteinGrams","carbsGrams","fatGrams","barcode"));Map<String,Object> fields=Map.ofEntries(Map.entry("type",Map.of("type","string","enum",List.of("LOG_MEAL","QUERY_JOURNAL","EDIT_ENTRY","DELETE_ENTRY","UPDATE_SETTINGS","SAVE_PRIVATE_FOOD","CHAT"))),Map.entry("mealDescription",Map.of("type",List.of("string","null"))),Map.entry("calories",nullableInteger),Map.entry("query",Map.of("type",List.of("string","null"))),Map.entry("entryId",nullableInteger),Map.entry("timezone",Map.of("type",List.of("string","null"))),Map.entry("calorieTarget",nullableInteger),Map.entry("reportsEnabled",Map.of("type",List.of("boolean","null"))),Map.entry("items",Map.of("type","array","items",item)),Map.entry("eatenAt",Map.of("type",List.of("string","null"))),Map.entry("nutritionSource",Map.of("type",List.of("string","null"))),Map.entry("confidence",Map.of("type",List.of("string","null"))));Map<String,Object> schema=Map.of("name","journal_command","strict",true,"schema",Map.of("type","object","additionalProperties",false,"properties",fields,"required",List.of("type","mealDescription","calories","query","entryId","timezone","calorieTarget","reportsEnabled","items","eatenAt","nutritionSource","confidence")));String instructions="Interpret Romanian, English, and mixed-language food-journal messages as one safe command. For each food output grams and either totalCalories or caloriesPer100g; never put kcal per 100 g in totalCalories. Example: 165 g crispy at 229 kcal per 100 g => grams=165, caloriesPer100g=229. Example: 66 kcal x 4.5 cocoa milk => totalCalories=297. Split separate foods into separate items. For total azi, total today, cate calorii azi return QUERY_JOURNAL. Never invent IDs, quantities, barcode, or nutrition facts.";Map<String,Object> body=Map.of("model",props.openaiModel(),"response_format",Map.of("type","json_schema","json_schema",schema),"messages",List.of(Map.of("role","system","content",instructions),Map.of("role","user","content",message)));JsonNode json=client.post().uri("/chat/completions").header("Authorization","Bearer "+props.openaiApiKey()).body(body).retrieve().body(JsonNode.class);JournalIntent intent=mapper.readValue(json.at("/choices/0/message/content").asText(),JournalIntent.class);return valid(intent)?intent:safe();}catch(Exception ignored){return safe();}}
 private boolean valid(JournalIntent intent){return intent!=null&&intent.type()!=null&&(intent.items()==null||intent.items().stream().allMatch(Objects::nonNull));}
 private JournalIntent safe(){return new JournalIntent(IntentType.CHAT,null,null,null,null,null,null,null,List.of());}
}
